    if n < 0:
        raise ValueError("n debe ser no negativo")
    izq, der = 0, n
    while izq <= der:
        mid = (izq + der) // 2
        if mid * mid == n:
            return mid
        if mid * mid < n:
            izq = mid + 1
            ultimo = mid
        else:
            der = mid - 1
    return ultimo

print(raiz_cuadrada_entera(8))   # 2
print(raiz_cuadrada_entera(25))  # 5

def encontrar_pico(arr: list) -> int:
    """Encontrar cualquier elemento pico (mayor a sus vecinos)."""
    izq, der = 0, len(arr) - 1
    while izq < der:
        mid = (izq + der) // 2
        if arr[mid] > arr[mid + 1]:
            der = mid
        else:
            izq = mid + 1
    return izq

