def rotated_search(arr: list, objetivo: int) -> int:
    """Búsqueda binaria en array rotado."""
    izq, der = 0, len(arr) - 1
    while izq <= der:
        mid = (izq + der) // 2
        if arr[mid] == objetivo:
            return mid
        if arr[izq] <= arr[mid]:  # izquierda ordenada
            if arr[izq] <= objetivo < arr[mid]:
                der = mid - 1
            else:
                izq = mid + 1
        else:  # derecha ordenada
            if arr[mid] < objetivo <= arr[der]:
                izq = mid + 1
            else:
                der = mid - 1
    return -1

